// 1. Zugriff auf die Daten der vorherigen Nodes
// "Postgres1" muss exakt so heißen wie dein Postgres-Node aus Schritt 1!
// Falls er anders heißt, passe den Namen hier an: $('DeinPostgresNodeName').first().json.last_date
const lastDateStr = $('Postgres').first().json.last_date; 
const apiData = $input.first().json; // Daten vom HTTP Request

// 2. Hilfsfunktionen für Datum
function addDays(dateStr, days) {
  const date = new Date(dateStr);
  date.setDate(date.getDate() + days);
  return date.toISOString().split('T')[0];
}

function getYesterday() {
  const date = new Date();
  date.setDate(date.getDate() - 1);
  return date.toISOString().split('T')[0];
}

// 3. Start- und Enddatum bestimmen
let nextDateToFetch;
if (!lastDateStr) {
  // Fallback: Wenn DB leer ist, hole nur gestern (oder ein festes Startdatum setzen)
  nextDateToFetch = getYesterday(); 
} else {
  nextDateToFetch = addDays(lastDateStr, 1);
}

const yesterday = getYesterday();
const results = [];

// 4. Daten-Container vorbereiten (aus dem API JSON)
const datasets = apiData.MonthCurves.Datasets;
const unit = apiData.MonthCurves.Unit;

// Hilfsfunktion zum Extrahieren (ähnlich wie vorher, aber robust für Monate)
function getVal(type, dateStr) {
  const dataset = datasets.find(d => d.Type === type);
  if (!dataset) return null;

  const monthStr = dateStr.substring(0, 7); // "2023-10"
  const day = parseInt(dateStr.substring(8, 10), 10);

  const monthData = dataset.Data.find(d => d.Timestamp === monthStr);
  if (monthData && monthData.Data && monthData.Data[day-1] !== undefined) {
    return monthData.Data[day-1];
  }
  return null;
}

// 5. LOOP: Von "letztes DB Datum + 1" bis "Gestern"
while (nextDateToFetch <= yesterday) {

  const prod = getVal("Produced", nextDateToFetch);
  const cons = getVal("Consumed", nextDateToFetch);
  const inj  = getVal("Injected", nextDateToFetch);

  // Nur hinzufügen, wenn wir Daten gefunden haben (API hat evtl. nicht unendlich Historie)
  if (prod !== null && cons !== null && inj !== null) {
    results.push({
      json: {
        date_of_production: nextDateToFetch,
        produced: prod,
        consumed: cons,
        injected: inj,
        unit: unit
      }
    });
  }

  // Tag hochzählen
  nextDateToFetch = addDays(nextDateToFetch, 1);

  // Sicherheits-Break (falls Loop endlos läuft, z.B. max 365 Tage)
  if (results.length > 365) break; 
}

// 6. Rückgabe: n8n wird den nächsten Node nun für JEDEN Eintrag in diesem Array ausführen
return results;
